const LANG_META={
 ar:{dir:"rtl",voice:"ar-SA"}, en:{dir:"ltr",voice:"en-US"}, nl:{dir:"ltr",voice:"nl-NL"},
 he:{dir:"rtl",voice:"he-IL"}, jv:{dir:"ltr",voice:"jv-ID"}, id:{dir:"ltr",voice:"id-ID"},
 fr:{dir:"ltr",voice:"fr-FR"}, es:{dir:"ltr",voice:"es-ES"}, de:{dir:"ltr",voice:"de-DE"}, tr:{dir:"ltr",voice:"tr-TR"}
};
const CORE_LANGS=["ar","en","nl","he","jv","id","fr","es","de","tr"];
let LANG=(window.LuxLang&&window.LuxLang.get())||"en";
if(!CORE_LANGS.includes(LANG))LANG="en";
function t(k){
 const own=TX[LANG]&&TX[LANG][k];
 if(own!==undefined&&own!==null&&own!=="")return own;
 if(LANG==="ar")return TX.ar[k]||"";
 return (TX.en&&TX.en[k])||"";
}
function applyLang(){
 document.documentElement.lang=LANG;
 document.documentElement.dir=LANG_META[LANG].dir;
 if(document.body){document.body.classList.toggle("rtl-core",LANG==="ar"||LANG==="he");document.body.dataset.lang=LANG}
 document.querySelectorAll("[data-t]").forEach(e=>{e.textContent=t(e.dataset.t)});
 document.querySelectorAll("[data-ph]").forEach(e=>{e.placeholder=t(e.dataset.ph)});
 document.querySelectorAll("[data-lang-select]").forEach(e=>{
   e.value=LANG;const lm={ar:"langAr",en:"langEn",nl:"langNl",he:"langHe",jv:"langJv",id:"langId",fr:"langFr",es:"langEs",de:"langDe",tr:"langTr"};
   const labels={ar:"العربية",en:"English",nl:"Nederlands",he:"עברית",jv:"Basa Jawa",id:"Bahasa Indonesia",fr:"Français",es:"Español",de:"Deutsch",tr:"Türkçe"};
   [...e.options].forEach(o=>{o.textContent=labels[o.value]||o.textContent});
 });
 const tk=document.body&&document.body.dataset.titleKey;document.title=tk?t(tk):"LuxDot";
 stripTerminalDots();
}
function setLang(l){if(!CORE_LANGS.includes(l))return;LANG=l;if(window.LuxLang)window.LuxLang.set(l,true);else{localStorage.setItem("luxdot.lang",LANG);localStorage.setItem("luxdot.lang.explicit","1")}applyLang();document.dispatchEvent(new CustomEvent("luxlang",{detail:{lang:LANG}}))}
function stripTerminalDots(root=document.body){
 if(!root)return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;
 while(n=w.nextNode()){if(n.parentElement&&/^(SCRIPT|STYLE|CODE|PRE)$/i.test(n.parentElement.tagName))continue;n.nodeValue=n.nodeValue.replace(/[.。]+(?=\s*$)/g,"")}
}
function stopSpeech(){if("speechSynthesis" in window)window.speechSynthesis.cancel()}
function speakText(text,lang=LANG){
 if(!("speechSynthesis" in window)||!text)return false;stopSpeech();const u=new SpeechSynthesisUtterance(text);
 const target=(LANG_META[lang]||LANG_META.ar).voice.toLowerCase();const voices=window.speechSynthesis.getVoices();
 u.voice=voices.find(v=>v.lang&&v.lang.toLowerCase()===target)||voices.find(v=>v.lang&&v.lang.toLowerCase().startsWith(target.slice(0,2)))||null;
 u.lang=u.voice?.lang||target;u.rate=.92;u.pitch=1;window.speechSynthesis.speak(u);return true
}
document.addEventListener("DOMContentLoaded",()=>{applyLang();document.querySelectorAll("[data-lang-select]").forEach(s=>s.addEventListener("change",e=>setLang(e.target.value)))})
